public class Bird
{
    public virtual void Fly() => Console.WriteLine("Flying");
}

public class Penguin : Bird
{
    public override void Fly() => throw new NotSupportedException("Penguins can't fly!");
}

// This breaks when passing a Penguin
public void MakeBirdFly(Bird bird)
{
    bird.Fly(); // Throws for Penguin!
}

public interface IBird
{
    void Eat();
}

public interface IFlyingBird : IBird
{
    void Fly();
}

public class Sparrow : IFlyingBird
{
    public void Eat() => Console.WriteLine("Eating");
    public void Fly() => Console.WriteLine("Flying");
}

public class Penguin : IBird
{
    public void Eat() => Console.WriteLine("Eating fish");
    // No Fly method - penguins don't fly
}
